export function qualityRecords() {
  return Object.fromEntries(Object.entries(answers).map(([label, users]) => {
    const messages = []
    for (const [index, text] of users.entries()) {
      const add = (speakerId, speakerName, body) => {
        const n = messages.length + 1
        messages.push({ id: `q-${n}`, order: n, turnId: n, speakerId, speakerName, isUser: speakerId === 'user', text: body,
          timestamp: 1000 + n * 20000, elapsedMs: n * 20000, source: speakerId === 'user' ? 'text' : 'mock' })
      }
      add(`ai${index + 1}`, ['김지훈', '이서연', '박민수'][index], ai[index])
      add('user', '나', text)
    }
    return [label, { schemaVersion: 1, id: 'synthetic-quality-record', topic: { id: 'quality-practice', title: 'AI가 채용에서 탈락시킬 지원자를 결정해도 될까?', source: 'custom', category: '직접 입력' },
      startedAt: 1000, endedAt: 181000, durationMs: 180000, mode: 'normal', modelSettings: null, messages }]
  }))
}
